def transform(grid):
    """Move each non-background object right until blocked by the edge or another object."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr,nc)); stack.append((nr,nc))
            objects.append(cells)
    # Rightmost objects move first, allowing objects ahead to settle against the boundary.
    objects.sort(key=lambda cells: max(c for _,c in cells), reverse=True)
    for cells in objects:
        for r,c in cells:
            out[r][c] = 0
        shift = 0
        while True:
            nxt = shift + 1
            if any(c+nxt >= w or (out[r][c+nxt] != 0 and (r,c+nxt) not in cells)
                   for r,c in cells):
                break
            shift = nxt
        for r,c in cells:
            out[r][c+shift] = grid[r][c]
    return out
